insert into public.topics values ('place-value','{"id":"place-value","title":"Натуральные числа: разряды, классы, чтение и запись больших чисел","area":"number","prerequisites":[],"objective":"Читаем и записываем натуральные числа по разрядам.","lesson":"У каждой цифры есть разряд: справа налево идут единицы, десятки, сотни и тысячи. При переходе на один разряд влево значение цифры увеличивается в десять раз.","example":"В числе 3 742 цифра 7 означает 7 сотен, то есть 700. Число можно записать как 3 000 + 700 + 40 + 2.","minutes":8,"practice":{"id":"place-value-guided","prompt":"Какое значение имеет цифра 2 в числе 2 481?","choices":["2000","200","20","2"],"answer":0,"explanation":"Цифра стоит в разряде тысяч: 2 × 1 000 = 2000.","hint":"Считайте разряды справа налево: единицы, десятки, сотни, тысячи."},"checks":[{"id":"place-value-check-1","prompt":"Какое значение имеет цифра 3 в числе 3 481?","choices":["300","30","3","3000"],"answer":3,"explanation":"Цифра стоит в разряде тысяч: 3 × 1 000 = 3000.","hint":"Считайте разряды справа налево: единицы, десятки, сотни, тысячи."},{"id":"place-value-check-2","prompt":"Какое значение имеет цифра 4 в числе 4 481?","choices":["40","4","4000","400"],"answer":2,"explanation":"Цифра стоит в разряде тысяч: 4 × 1 000 = 4000.","hint":"Считайте разряды справа налево: единицы, десятки, сотни, тысячи."},{"id":"place-value-check-3","prompt":"Какое значение имеет цифра 5 в числе 5 481?","choices":["5","5000","500","50"],"answer":1,"explanation":"Цифра стоит в разряде тысяч: 5 × 1 000 = 5000.","hint":"Считайте разряды справа налево: единицы, десятки, сотни, тысячи."},{"id":"place-value-check-4","prompt":"Какое значение имеет цифра 6 в числе 6 481?","choices":["6000","600","60","6"],"answer":0,"explanation":"Цифра стоит в разряде тысяч: 6 × 1 000 = 6000.","hint":"Считайте разряды справа налево: единицы, десятки, сотни, тысячи."},{"id":"place-value-check-5","prompt":"Какое значение имеет цифра 7 в числе 7 481?","choices":["700","70","7","7000"],"answer":3,"explanation":"Цифра стоит в разряде тысяч: 7 × 1 000 = 7000.","hint":"Считайте разряды справа налево: единицы, десятки, сотни, тысячи."},{"id":"place-value-check-6","prompt":"Какое значение имеет цифра 8 в числе 8 481?","choices":["80","8","8000","800"],"answer":2,"explanation":"Цифра стоит в разряде тысяч: 8 × 1 000 = 8000.","hint":"Считайте разряды справа налево: единицы, десятки, сотни, тысячи."}],"sectionId":"section-01","order":1}'::jsonb) on conflict(id) do nothing;
