insert into public.topics values ('operations','{"id":"operations","title":"Порядок действий и роль скобок","area":"number","prerequisites":["place-value"],"objective":"Выполняем умножение раньше сложения.","lesson":"Порядок действий позволяет всем одинаково понимать выражение. Сначала выполните действия в скобках, затем умножение и деление, в конце — сложение и вычитание.","example":"В выражении 5 + 3 × 4 сначала умножаем: 3 × 4 = 12. Затем 5 + 12 = 17.","minutes":8,"practice":{"id":"operations-guided","prompt":"3 + 4 × 3 = ?","choices":["15","21","10","12"],"answer":0,"explanation":"4 × 3 = 12. Затем 3 + 12 = 15.","hint":"Выполните умножение перед сложением."},"checks":[{"id":"operations-check-1","prompt":"4 + 4 × 3 = ?","choices":["24","11","13","16"],"answer":3,"explanation":"4 × 3 = 12. Затем 4 + 12 = 16.","hint":"Выполните умножение перед сложением."},{"id":"operations-check-2","prompt":"5 + 4 × 3 = ?","choices":["12","14","17","27"],"answer":2,"explanation":"4 × 3 = 12. Затем 5 + 12 = 17.","hint":"Выполните умножение перед сложением."},{"id":"operations-check-3","prompt":"6 + 4 × 3 = ?","choices":["15","18","30","13"],"answer":1,"explanation":"4 × 3 = 12. Затем 6 + 12 = 18.","hint":"Выполните умножение перед сложением."},{"id":"operations-check-4","prompt":"7 + 4 × 3 = ?","choices":["19","33","14","16"],"answer":0,"explanation":"4 × 3 = 12. Затем 7 + 12 = 19.","hint":"Выполните умножение перед сложением."},{"id":"operations-check-5","prompt":"8 + 4 × 3 = ?","choices":["36","15","17","20"],"answer":3,"explanation":"4 × 3 = 12. Затем 8 + 12 = 20.","hint":"Выполните умножение перед сложением."},{"id":"operations-check-6","prompt":"9 + 4 × 3 = ?","choices":["16","18","21","39"],"answer":2,"explanation":"4 × 3 = 12. Затем 9 + 12 = 21.","hint":"Выполните умножение перед сложением."}],"sectionId":"section-01","order":6}'::jsonb) on conflict(id) do nothing;
