insert into public.topics values ('angles','{"id":"angles","title":"Угол и его виды; измерение транспортиром","area":"geometry","prerequisites":["operations"],"objective":"Находим неизвестный угол на прямой.","lesson":"Углы измеряются в градусах. Половина полного оборота — 180°. Сумма смежных углов, образующих прямую, равна 180°.","example":"Если один из смежных углов равен 65°, другой равен 180° − 65° = 115°.","minutes":8,"practice":{"id":"angles-guided","prompt":"Два смежных угла образуют прямую. Один равен 40°. Найдите другой.","choices":["140°","150°","130°","320°"],"answer":0,"explanation":"180° − 40° = 140°.","hint":"Развёрнутый угол равен половине оборота: 180 градусов."},"checks":[{"id":"angles-check-1","prompt":"Два смежных угла образуют прямую. Один равен 50°. Найдите другой.","choices":["140°","120°","310°","130°"],"answer":3,"explanation":"180° − 50° = 130°.","hint":"Развёрнутый угол равен половине оборота: 180 градусов."},{"id":"angles-check-2","prompt":"Два смежных угла образуют прямую. Один равен 60°. Найдите другой.","choices":["110°","300°","120°","130°"],"answer":2,"explanation":"180° − 60° = 120°.","hint":"Развёрнутый угол равен половине оборота: 180 градусов."},{"id":"angles-check-3","prompt":"Два смежных угла образуют прямую. Один равен 70°. Найдите другой.","choices":["290°","110°","120°","100°"],"answer":1,"explanation":"180° − 70° = 110°.","hint":"Развёрнутый угол равен половине оборота: 180 градусов."},{"id":"angles-check-4","prompt":"Два смежных угла образуют прямую. Один равен 80°. Найдите другой.","choices":["100°","110°","90°","280°"],"answer":0,"explanation":"180° − 80° = 100°.","hint":"Развёрнутый угол равен половине оборота: 180 градусов."},{"id":"angles-check-5","prompt":"Два смежных угла образуют прямую. Один равен 90°. Найдите другой.","choices":["100°","80°","270°","90°"],"answer":3,"explanation":"180° − 90° = 90°.","hint":"Развёрнутый угол равен половине оборота: 180 градусов."},{"id":"angles-check-6","prompt":"Два смежных угла образуют прямую. Один равен 100°. Найдите другой.","choices":["70°","260°","80°","90°"],"answer":2,"explanation":"180° − 100° = 80°.","hint":"Развёрнутый угол равен половине оборота: 180 градусов."}],"sectionId":"section-02","order":9}'::jsonb) on conflict(id) do nothing;
insert into public.topics values ('perimeter','{"id":"perimeter","title":"Прямоугольник и квадрат: периметр и площадь","area":"geometry","prerequisites":["operations"],"objective":"Находим периметр прямоугольника.","lesson":"Периметр — это сумма длин всех сторон фигуры. У прямоугольника противоположные стороны равны. Сложите длины всех четырёх сторон.","example":"Периметр прямоугольника со сторонами 6 см и 4 см: 6 + 4 + 6 + 4 = 20 см.","minutes":8,"practice":{"id":"perimeter-guided","prompt":"Длина прямоугольника — 4 см, ширина — 3 см. Чему равен периметр?","choices":["14 см","16 см","7 см","12 см"],"answer":0,"explanation":"Сложите длины всех сторон: 4 + 3 + 4 + 3 = 14 см.","hint":"Учтите две длины и две ширины."},"checks":[{"id":"perimeter-check-1","prompt":"Длина прямоугольника — 5 см, ширина — 3 см. Чему равен периметр?","choices":["18 см","8 см","14 см","16 см"],"answer":3,"explanation":"Сложите длины всех сторон: 5 + 3 + 5 + 3 = 16 см.","hint":"Учтите две длины и две ширины."},{"id":"perimeter-check-2","prompt":"Длина прямоугольника — 6 см, ширина — 3 см. Чему равен периметр?","choices":["9 см","16 см","18 см","20 см"],"answer":2,"explanation":"Сложите длины всех сторон: 6 + 3 + 6 + 3 = 18 см.","hint":"Учтите две длины и две ширины."},{"id":"perimeter-check-3","prompt":"Длина прямоугольника — 7 см, ширина — 3 см. Чему равен периметр?","choices":["18 см","20 см","22 см","10 см"],"answer":1,"explanation":"Сложите длины всех сторон: 7 + 3 + 7 + 3 = 20 см.","hint":"Учтите две длины и две ширины."},{"id":"perimeter-check-4","prompt":"Длина прямоугольника — 8 см, ширина — 3 см. Чему равен периметр?","choices":["22 см","24 см","11 см","20 см"],"answer":0,"explanation":"Сложите длины всех сторон: 8 + 3 + 8 + 3 = 22 см.","hint":"Учтите две длины и две ширины."},{"id":"perimeter-check-5","prompt":"Длина прямоугольника — 9 см, ширина — 3 см. Чему равен периметр?","choices":["26 см","12 см","22 см","24 см"],"answer":3,"explanation":"Сложите длины всех сторон: 9 + 3 + 9 + 3 = 24 см.","hint":"Учтите две длины и две ширины."},{"id":"perimeter-check-6","prompt":"Длина прямоугольника — 10 см, ширина — 3 см. Чему равен периметр?","choices":["13 см","24 см","26 см","28 см"],"answer":2,"explanation":"Сложите длины всех сторон: 10 + 3 + 10 + 3 = 26 см.","hint":"Учтите две длины и две ширины."}],"sectionId":"section-02","order":10}'::jsonb) on conflict(id) do nothing;
