insert into public.topics values ('add-fractions','{"id":"add-fractions","title":"Сложение и вычитание дробей","area":"fractions","prerequisites":["equivalent"],"objective":"Складываем дроби, приводя их к общему знаменателю.","lesson":"Складывать части можно, когда они одинакового размера. Приведите дроби к общему знаменателю, сложите числители, а знаменатель оставьте прежним.","example":"1/2 + 1/4 = 2/4 + 1/4 = 3/4. Знаменатель остаётся равным 4, потому что мы считаем четверти.","minutes":8,"practice":{"id":"add-fractions-guided","prompt":"1/2 + 1/4 = ? (Выберите равную сумму.)","choices":["3/4","2/6","2/4","1/4"],"answer":0,"explanation":"1/2 = 2/4. Прибавьте 1 к числителю: получится 3/4.","hint":"Замените 1/2 равной дробью с нужным знаменателем."},"checks":[{"id":"add-fractions-check-1","prompt":"1/2 + 1/6 = ? (Выберите равную сумму.)","choices":["2/8","3/6","1/6","4/6"],"answer":3,"explanation":"1/2 = 3/6. Прибавьте 1 к числителю: получится 4/6.","hint":"Замените 1/2 равной дробью с нужным знаменателем."},{"id":"add-fractions-check-2","prompt":"1/2 + 1/8 = ? (Выберите равную сумму.)","choices":["4/8","1/8","5/8","2/10"],"answer":2,"explanation":"1/2 = 4/8. Прибавьте 1 к числителю: получится 5/8.","hint":"Замените 1/2 равной дробью с нужным знаменателем."},{"id":"add-fractions-check-3","prompt":"1/2 + 1/10 = ? (Выберите равную сумму.)","choices":["1/10","6/10","2/12","5/10"],"answer":1,"explanation":"1/2 = 5/10. Прибавьте 1 к числителю: получится 6/10.","hint":"Замените 1/2 равной дробью с нужным знаменателем."},{"id":"add-fractions-check-4","prompt":"1/2 + 1/12 = ? (Выберите равную сумму.)","choices":["7/12","2/14","6/12","1/12"],"answer":0,"explanation":"1/2 = 6/12. Прибавьте 1 к числителю: получится 7/12.","hint":"Замените 1/2 равной дробью с нужным знаменателем."},{"id":"add-fractions-check-5","prompt":"1/2 + 1/14 = ? (Выберите равную сумму.)","choices":["2/16","7/14","1/14","8/14"],"answer":3,"explanation":"1/2 = 7/14. Прибавьте 1 к числителю: получится 8/14.","hint":"Замените 1/2 равной дробью с нужным знаменателем."},{"id":"add-fractions-check-6","prompt":"1/2 + 1/16 = ? (Выберите равную сумму.)","choices":["8/16","1/16","9/16","2/18"],"answer":2,"explanation":"1/2 = 8/16. Прибавьте 1 к числителю: получится 9/16.","hint":"Замените 1/2 равной дробью с нужным знаменателем."}],"sectionId":"section-05","order":25}'::jsonb) on conflict(id) do nothing;
