insert into public.topics values ('averages','{"id":"averages","title":"Среднее арифметическое","area":"data","prerequisites":["operations"],"objective":"Находим среднее арифметическое нескольких чисел.","lesson":"Чтобы найти среднее арифметическое, сложите все значения и разделите сумму на их количество. Нули тоже учитываются, если они есть в наборе данных.","example":"Среднее арифметическое чисел 2, 4 и 9: (2 + 4 + 9) ÷ 3 = 5.","minutes":8,"practice":{"id":"averages-guided","prompt":"Найдите среднее арифметическое чисел 2, 4 и 6.","choices":["4","12","2","6"],"answer":0,"explanation":"Сумма равна 12. Делим на количество чисел, то есть на 3: 4.","hint":"Сложите три числа и разделите сумму на 3."},"checks":[{"id":"averages-check-1","prompt":"Найдите среднее арифметическое чисел 3, 5 и 7.","choices":["15","3","7","5"],"answer":3,"explanation":"Сумма равна 15. Делим на количество чисел, то есть на 3: 5.","hint":"Сложите три числа и разделите сумму на 3."},{"id":"averages-check-2","prompt":"Найдите среднее арифметическое чисел 4, 6 и 8.","choices":["4","8","6","18"],"answer":2,"explanation":"Сумма равна 18. Делим на количество чисел, то есть на 3: 6.","hint":"Сложите три числа и разделите сумму на 3."},{"id":"averages-check-3","prompt":"Найдите среднее арифметическое чисел 5, 7 и 9.","choices":["9","7","21","5"],"answer":1,"explanation":"Сумма равна 21. Делим на количество чисел, то есть на 3: 7.","hint":"Сложите три числа и разделите сумму на 3."},{"id":"averages-check-4","prompt":"Найдите среднее арифметическое чисел 6, 8 и 10.","choices":["8","24","6","10"],"answer":0,"explanation":"Сумма равна 24. Делим на количество чисел, то есть на 3: 8.","hint":"Сложите три числа и разделите сумму на 3."},{"id":"averages-check-5","prompt":"Найдите среднее арифметическое чисел 7, 9 и 11.","choices":["27","7","11","9"],"answer":3,"explanation":"Сумма равна 27. Делим на количество чисел, то есть на 3: 9.","hint":"Сложите три числа и разделите сумму на 3."},{"id":"averages-check-6","prompt":"Найдите среднее арифметическое чисел 8, 10 и 12.","choices":["8","12","10","30"],"answer":2,"explanation":"Сумма равна 30. Делим на количество чисел, то есть на 3: 10.","hint":"Сложите три числа и разделите сумму на 3."}],"sectionId":"section-06","order":32}'::jsonb) on conflict(id) do nothing;
