insert into public.topics values ('ratios','{"id":"ratios","title":"Отношение двух величин: что оно показывает","area":"fractions","prerequisites":["equivalent"],"objective":"Изменяем количества, сохраняя их отношение.","lesson":"Отношение сравнивает количества. Если напиток состоит из 1 части сока и 3 частей воды, всего получается 4 части. Чтобы сохранить вкус, увеличивайте оба количества в одинаковое число раз.","example":"На 2 стакана сока при отношении 1 : 3 нужно 6 стаканов воды. Отношение сохраняется: 2 : 6 = 1 : 3.","minutes":8,"practice":{"id":"ratios-guided","prompt":"В напитке сок и вода относятся как 1 : 3. Сколько стаканов воды нужно на 2 стакана сока?","choices":["6","5","2","8"],"answer":0,"explanation":"Умножьте обе части на 2: нужно 6 стаканов воды.","hint":"На каждый стакан сока приходится 3 стакана воды."},"checks":[{"id":"ratios-check-1","prompt":"В напитке сок и вода относятся как 1 : 3. Сколько стаканов воды нужно на 3 стакана сока?","choices":["6","3","12","9"],"answer":3,"explanation":"Умножьте обе части на 3: нужно 9 стаканов воды.","hint":"На каждый стакан сока приходится 3 стакана воды."},{"id":"ratios-check-2","prompt":"В напитке сок и вода относятся как 1 : 3. Сколько стаканов воды нужно на 4 стакана сока?","choices":["4","16","12","7"],"answer":2,"explanation":"Умножьте обе части на 4: нужно 12 стаканов воды.","hint":"На каждый стакан сока приходится 3 стакана воды."},{"id":"ratios-check-3","prompt":"В напитке сок и вода относятся как 1 : 3. Сколько стаканов воды нужно на 5 стакана сока?","choices":["20","15","8","5"],"answer":1,"explanation":"Умножьте обе части на 5: нужно 15 стаканов воды.","hint":"На каждый стакан сока приходится 3 стакана воды."},{"id":"ratios-check-4","prompt":"В напитке сок и вода относятся как 1 : 3. Сколько стаканов воды нужно на 6 стакана сока?","choices":["18","9","6","24"],"answer":0,"explanation":"Умножьте обе части на 6: нужно 18 стаканов воды.","hint":"На каждый стакан сока приходится 3 стакана воды."},{"id":"ratios-check-5","prompt":"В напитке сок и вода относятся как 1 : 3. Сколько стаканов воды нужно на 7 стакана сока?","choices":["10","7","28","21"],"answer":3,"explanation":"Умножьте обе части на 7: нужно 21 стаканов воды.","hint":"На каждый стакан сока приходится 3 стакана воды."},{"id":"ratios-check-6","prompt":"В напитке сок и вода относятся как 1 : 3. Сколько стаканов воды нужно на 8 стакана сока?","choices":["8","32","24","11"],"answer":2,"explanation":"Умножьте обе части на 8: нужно 24 стаканов воды.","hint":"На каждый стакан сока приходится 3 стакана воды."}],"sectionId":"section-07","order":34}'::jsonb) on conflict(id) do nothing;
