insert into public.topics values ('patterns','{"id":"patterns","title":"Числовые закономерности","area":"algebra","prerequisites":["operations"],"objective":"Находим правило и продолжаем последовательность с постоянным шагом.","lesson":"Найдите разность соседних чисел. Если она каждый раз одинакова, прибавляйте этот шаг, чтобы продолжить последовательность.","example":"В последовательности 4, 7, 10, 13 каждое следующее число больше предыдущего на 3. Следующее число — 16.","minutes":8,"practice":{"id":"patterns-guided","prompt":"Продолжите: 1, 5, 9, …","choices":["13","12","14","18"],"answer":0,"explanation":"Шаг каждый раз равен +4. 9 + 4 = 13.","hint":"Вычтите первое число из второго."},"checks":[{"id":"patterns-check-1","prompt":"Продолжите: 2, 6, 10, …","choices":["13","15","19","14"],"answer":3,"explanation":"Шаг каждый раз равен +4. 10 + 4 = 14.","hint":"Вычтите первое число из второго."},{"id":"patterns-check-2","prompt":"Продолжите: 3, 7, 11, …","choices":["16","20","15","14"],"answer":2,"explanation":"Шаг каждый раз равен +4. 11 + 4 = 15.","hint":"Вычтите первое число из второго."},{"id":"patterns-check-3","prompt":"Продолжите: 4, 8, 12, …","choices":["21","16","15","17"],"answer":1,"explanation":"Шаг каждый раз равен +4. 12 + 4 = 16.","hint":"Вычтите первое число из второго."},{"id":"patterns-check-4","prompt":"Продолжите: 5, 9, 13, …","choices":["17","16","18","22"],"answer":0,"explanation":"Шаг каждый раз равен +4. 13 + 4 = 17.","hint":"Вычтите первое число из второго."},{"id":"patterns-check-5","prompt":"Продолжите: 6, 10, 14, …","choices":["17","19","23","18"],"answer":3,"explanation":"Шаг каждый раз равен +4. 14 + 4 = 18.","hint":"Вычтите первое число из второго."},{"id":"patterns-check-6","prompt":"Продолжите: 7, 11, 15, …","choices":["20","24","19","18"],"answer":2,"explanation":"Шаг каждый раз равен +4. 15 + 4 = 19.","hint":"Вычтите первое число из второго."}]}'::jsonb) on conflict(id) do nothing;
insert into public.topics values ('area','{"id":"area","title":"Площадь прямоугольника","area":"geometry","prerequisites":["perimeter"],"objective":"Вычисляем площадь прямоугольника в квадратных единицах.","lesson":"Площадь показывает, сколько места занимает фигура на плоскости. Прямоугольник можно заполнить рядами единичных квадратов. Для нахождения площади умножьте длину на ширину.","example":"В прямоугольнике 5 см на 3 см помещается 3 ряда по 5 квадратов: 15 см². Периметр измеряет длину границы, а площадь — размер поверхности.","minutes":8,"practice":{"id":"area-guided","prompt":"Чему равна площадь прямоугольника со сторонами 4 см и 3 см?","choices":["12 см²","15 см²","7 см²","9 см²"],"answer":0,"explanation":"4 × 3 = 12 квадратных сантиметров.","hint":"Площадь считает квадраты: умножьте длину на ширину."},"checks":[{"id":"area-check-1","prompt":"Чему равна площадь прямоугольника со сторонами 5 см и 3 см?","choices":["18 см²","8 см²","12 см²","15 см²"],"answer":3,"explanation":"5 × 3 = 15 квадратных сантиметров.","hint":"Площадь считает квадраты: умножьте длину на ширину."},{"id":"area-check-2","prompt":"Чему равна площадь прямоугольника со сторонами 6 см и 3 см?","choices":["9 см²","15 см²","18 см²","21 см²"],"answer":2,"explanation":"6 × 3 = 18 квадратных сантиметров.","hint":"Площадь считает квадраты: умножьте длину на ширину."},{"id":"area-check-3","prompt":"Чему равна площадь прямоугольника со сторонами 7 см и 3 см?","choices":["18 см²","21 см²","24 см²","10 см²"],"answer":1,"explanation":"7 × 3 = 21 квадратных сантиметров.","hint":"Площадь считает квадраты: умножьте длину на ширину."},{"id":"area-check-4","prompt":"Чему равна площадь прямоугольника со сторонами 8 см и 3 см?","choices":["24 см²","27 см²","11 см²","21 см²"],"answer":0,"explanation":"8 × 3 = 24 квадратных сантиметров.","hint":"Площадь считает квадраты: умножьте длину на ширину."},{"id":"area-check-5","prompt":"Чему равна площадь прямоугольника со сторонами 9 см и 3 см?","choices":["30 см²","12 см²","24 см²","27 см²"],"answer":3,"explanation":"9 × 3 = 27 квадратных сантиметров.","hint":"Площадь считает квадраты: умножьте длину на ширину."},{"id":"area-check-6","prompt":"Чему равна площадь прямоугольника со сторонами 10 см и 3 см?","choices":["13 см²","27 см²","30 см²","33 см²"],"answer":2,"explanation":"10 × 3 = 30 квадратных сантиметров.","hint":"Площадь считает квадраты: умножьте длину на ширину."}]}'::jsonb) on conflict(id) do nothing;
insert into public.topics values ('probability','{"id":"probability","title":"Вероятность события","area":"data","prerequisites":["equivalent","averages"],"objective":"Находим вероятность при равновозможных исходах.","lesson":"Вероятность — отношение числа благоприятных исходов к общему числу равновозможных исходов. Вероятность невозможного события равна 0, а достоверного — 1.","example":"В мешке 3 синие и 2 красные фишки. Вероятность случайно достать синюю: 3/5, потому что из 5 фишек 3 — синие.","minutes":8,"practice":{"id":"probability-guided","prompt":"В мешке 2 синих и 3 красные фишки. Какова вероятность случайно достать синюю?","choices":["2/5","3/5","2/6","1/5"],"answer":0,"explanation":"Всего 5 фишек, из них 2 — синие. Вероятность равна 2/5.","hint":"Разделите число синих фишек на общее число фишек."},"checks":[{"id":"probability-check-1","prompt":"В мешке 3 синих и 3 красные фишки. Какова вероятность случайно достать синюю?","choices":["4/6","3/7","1/6","3/6"],"answer":3,"explanation":"Всего 6 фишек, из них 3 — синие. Вероятность равна 3/6.","hint":"Разделите число синих фишек на общее число фишек."},{"id":"probability-check-2","prompt":"В мешке 4 синих и 3 красные фишки. Какова вероятность случайно достать синюю?","choices":["4/8","1/7","4/7","5/7"],"answer":2,"explanation":"Всего 7 фишек, из них 4 — синие. Вероятность равна 4/7.","hint":"Разделите число синих фишек на общее число фишек."},{"id":"probability-check-3","prompt":"В мешке 5 синих и 3 красные фишки. Какова вероятность случайно достать синюю?","choices":["1/8","5/8","6/8","5/9"],"answer":1,"explanation":"Всего 8 фишек, из них 5 — синие. Вероятность равна 5/8.","hint":"Разделите число синих фишек на общее число фишек."},{"id":"probability-check-4","prompt":"В мешке 6 синих и 3 красные фишки. Какова вероятность случайно достать синюю?","choices":["6/9","7/9","6/10","1/9"],"answer":0,"explanation":"Всего 9 фишек, из них 6 — синие. Вероятность равна 6/9.","hint":"Разделите число синих фишек на общее число фишек."},{"id":"probability-check-5","prompt":"В мешке 7 синих и 3 красные фишки. Какова вероятность случайно достать синюю?","choices":["8/10","7/11","1/10","7/10"],"answer":3,"explanation":"Всего 10 фишек, из них 7 — синие. Вероятность равна 7/10.","hint":"Разделите число синих фишек на общее число фишек."},{"id":"probability-check-6","prompt":"В мешке 8 синих и 3 красные фишки. Какова вероятность случайно достать синюю?","choices":["8/12","1/11","8/11","9/11"],"answer":2,"explanation":"Всего 11 фишек, из них 8 — синие. Вероятность равна 8/11.","hint":"Разделите число синих фишек на общее число фишек."}]}'::jsonb) on conflict(id) do nothing;
